import os
import zipfile
import tempfile
import shutil
from celery import Celery
from celery.utils.log import get_task_logger

app = Celery('document_processor', broker='redis://localhost:6379/0')
logger = get_task_logger(__name__)

UPLOAD_DIR = '/var/lib/docproc/uploads'
EXTRACT_DIR = '/var/lib/docproc/extracted'
PROCESSED_DIR = '/var/lib/docproc/processed'


def validate_archive_metadata(zip_path):
    """Check archive isn't suspiciously large or has too many entries."""
    with zipfile.ZipFile(zip_path, 'r') as zf:
        total_size = sum(info.file_size for info in zf.infolist())
        if total_size > 500 * 1024 * 1024:  # 500MB limit
            raise ValueError(f"Archive too large: {total_size} bytes")
        if len(zf.infolist()) > 1000:
            raise ValueError(f"Too many entries: {len(zf.infolist())}")
    return True


def sanitize_filename(filename):
    """Remove null bytes and normalize unicode in filenames."""
    filename = filename.replace('\x00', '')
    # Note: we preserve directory structure for nested document packages
    return filename.strip()


@app.task(bind=True, max_retries=3, default_retry_delay=60)
def process_document_archive(self, job_id, archive_filename, user_id):
    """Process uploaded document archive for indexing.

    Archives are uploaded via the internal API gateway which handles
    authentication and authorization before dispatching to the queue.
    """
    archive_path = os.path.join(UPLOAD_DIR, archive_filename)
    extract_path = os.path.join(EXTRACT_DIR, str(job_id))

    try:
        if not os.path.exists(archive_path):
            logger.error(f"Archive not found: {archive_path}")
            return {'status': 'error', 'message': 'Archive not found'}

        validate_archive_metadata(archive_path)

        os.makedirs(extract_path, exist_ok=True)

        with zipfile.ZipFile(archive_path, 'r') as zf:
            for member in zf.infolist():
                # Skip directories
                if member.is_dir():
                    continue

                # Sanitize the filename
                clean_name = sanitize_filename(member.filename)

                if not clean_name:
                    continue

                # Construct target path preserving internal structure
                target_path = os.path.join(extract_path, clean_name)

                # Ensure parent directories exist
                os.makedirs(os.path.dirname(target_path), exist_ok=True)

                # Extract file content
                with zf.open(member) as source:
                    with open(target_path, 'wb') as target:
                        shutil.copyfileobj(source, target)

                logger.info(f"Extracted: {clean_name} for job {job_id}")

        # Queue post-processing
        index_extracted_documents.delay(job_id, extract_path, user_id)

        return {'status': 'success', 'job_id': job_id, 'extract_path': extract_path}

    except zipfile.BadZipFile:
        logger.error(f"Invalid zip file: {archive_path}")
        return {'status': 'error', 'message': 'Invalid archive format'}
    except ValueError as e:
        logger.error(f"Validation failed: {e}")
        return {'status': 'error', 'message': str(e)}
    except Exception as exc:
        logger.exception(f"Unexpected error processing {archive_path}")
        self.retry(exc=exc)


@app.task
def index_extracted_documents(job_id, extract_path, user_id):
    """Index extracted documents into search engine."""
    indexed = 0
    for root, dirs, files in os.walk(extract_path):
        for fname in files:
            fpath = os.path.join(root, fname)
            # Simulated indexing logic
            logger.info(f"Indexing {fpath} for user {user_id}")
            indexed += 1

    return {'status': 'indexed', 'count': indexed, 'job_id': job_id}


@app.task
def cleanup_old_jobs(max_age_hours=24):
    """Periodic cleanup of old extraction directories."""
    import time
    now = time.time()
    for entry in os.scandir(EXTRACT_DIR):
        if entry.is_dir():
            age = now - entry.stat().st_mtime
            if age > max_age_hours * 3600:
                shutil.rmtree(entry.path)
                logger.info(f"Cleaned up old job directory: {entry.path}")
